import numpy as np

grid = np.array([[int(x) for x in row.split()] for row in grid_str.strip().split('\n')])
h, w = grid.shape

# Try: Expand each special value to nearby 5s within a small radius
# Keep special values as they are, replace surrounding 5s with the special value

def expand_value(grid, val, radius=2, preserve_special=True):
    output = grid.copy()
    h, w = output.shape
    for r in range(h):
        for c in range(w):
            if grid[r,c] == val:
                # Spread to nearby 5s
                for dr in range(-radius, radius+1):
                    for dc in range(-radius, radius+1):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if preserve_special and (r == nr and c == nc):
                                continue  # Don't overwrite the source
                            if grid[nr, nc] == 5:
                                output[nr, nc] = val
    return output

# Try with radius=2 for value 1
output_1 = expand_value(grid, 1, radius=2, preserve_special=False)
print("Expand 1s to nearby 5s (all other 5s become 0, except where 1s touch):")
print(f"Non-zero: {(output_1 > 0).sum()}")
print(output_1[:5])

